+  }
+  for (const module of [image, load('KERNEL32.dll'), load('unprovided.dll'), load('OLE32.dll'), 0x12345678]) {
+    assert.strictEqual(lookup(module, 8), 0, 'unrelated handles and image aliases must not become OLEAUT32');
